/// <summary>
/// Initializes default values for the extended fields.
/// </summary>
public void initValue()
{
    next initValue();

    this.AVARUMOverrideSettings = NoYes::No;
}

/// <summary>
/// Finds an inventory table module by item ID, distinct product variant, and module type.
/// </summary>
/// <param name = "_distinctProductVariant">Distinct product variant</param>
/// <param name = "_moduleType">Module type</param>
/// <param name = "_forUpdate">Indicates whether to perform an update</param>
/// <returns>Returns the found inventory table module; otherwise, null.</returns>
public static InventTableModule findByProductVariant_AVA(RefRecId _distinctProductVariant, ModuleInventPurchSales _moduleType, boolean _forUpdate = false)
{
    InventTableModule  inventTableModule;
    EcoResDistinctProductVariant productVariant;

    if (_forUpdate)
    {
        inventTableModule.selectForUpdate(_forUpdate);
        inventTableModule.selectLocked(_forUpdate);
    }

    if (_distinctProductVariant)
    {
        productVariant = EcoResDistinctProductVariant::find(_distinctProductVariant);

        select firstonly inventTableModule   
            where inventTableModule.ItemId == productVariant.DisplayProductNumber &&
                inventTableModule.ModuleType == _moduleType;

    }

    return inventTableModule;
}
